<template>
  <div class="saved-filter-badge row q-mt-sm q-ml-md">
    <span class="q-mr-xs" v-if="orderByMap.size > 0">{{ $t('sort_by') }}</span>
    <template v-for="[key, value] in orderByMap" :key="key">
      <q-badge rounded color="primary" class="q-mr-sm capitalize">
        {{ keyFormatter(column_ms_mapping[key]) }} : {{ value }}
        <q-icon
          name="close"
          color="white"
          class="q-ml-xs cursor-pointer"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocMasterDataLookUpStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
export default defineComponent({
  mixins: [displayFieldLabel],
  props: {},
  methods: {
    removeFilter(key: string) {
      this.orderByMap.delete(key);
      logInfo(this.orderByMap, 'order by map');
      this.triggerApplyFilters();
    },
    triggerApplyFilters() {
      const event = new CustomEvent('ms_search', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { orderByMap, column_ms_mapping } = storeToRefs(
      doc_ms_data_lookup_store,
    );

    return {
      column_ms_mapping,
      orderByMap,
    };
  },
});
</script>
